impl Solution {
    pub fn can_cross(a: Vec<u8>, m: usize, k: i64) -> bool {
        let n = a.len();
        let mut dp = vec![i64::MAX; n + 2];
        dp[0] = 0;

        for i in 1..=n + 1 {
            if dp[i] == i64::MAX {
                continue;
            }
            if i > 0 && i <= n && a[i - 1] == b'C' {
                continue;
            }
            let start = if i > m { i - m } else { 0 };
            for j in start..i {
                if dp[j] == i64::MAX {
                    continue;
                }
                let mut cost = dp[j];
                let mut pos = j;
                while pos < i {
                    if pos >= 1 && pos <= n && a[pos - 1] == b'W' {
                        cost += 1;
                    }
                    pos += 1;
                }
                if cost < dp[i] {
                    dp[i] = cost;
                }
            }
        }

        dp[n + 1] <= k
    }
}
